// DynamicAny (<rustorb/dynany.h>) with code generated by rustorb-idl
// -bc++11: DynAnys of generated types, valuetypes with sharing and cycles,
// truncation, and the classes and exceptions of the mapping. The cases of
// interop/impls/rustorbcpp/dynany_probe.cc cover the rest of the
// operations.

#include <algorithm>
#include <iostream>

#include "AnyTest.hh"
#include "valuetest.h"

struct CheckFailed {
  std::string message;
};

#define CHECK(cond)                                                                       \
  do {                                                                                    \
    if (!(cond)) throw CheckFailed{"line " + std::to_string(__LINE__) + ": " #cond}; \
  } while (0)

// CHECK that stmt throws E.
#define CHECK_THROWS(E, stmt)                                                    \
  do {                                                                           \
    bool thrown = false;                                                         \
    try {                                                                        \
      stmt;                                                                      \
    } catch (const E&) {                                                         \
      thrown = true;                                                             \
    }                                                                            \
    if (!thrown) throw CheckFailed{"line " + std::to_string(__LINE__) + ": no " #E}; \
  } while (0)

using namespace DynamicAny;
namespace A = AnyTest;
namespace V = ValueTest;
template <typename T> using ref = typename IDL::traits<T>::ref_type;

template <typename T> static ref<T> narrow(const DynAny_ref& d) { return IDL::traits<T>::narrow(d); }

template <typename T> static CORBA::Any any_of(const T& v) {
  CORBA::Any a;
  a <<= v;
  return a;
}

static void run(const std::string& name, const std::function<void()>& fn, int& failed) {
  try {
    fn();
    std::cout << "ok   " << name << std::endl;
    return;
  } catch (const CheckFailed& e) {
    std::cout << "FAIL " << name << ": " << e.message << std::endl;
  } catch (const CORBA::Exception& e) {
    std::cout << "FAIL " << name << ": unexpected " << e << std::endl;
  }
  ++failed;
}

int main(int argc, char** argv) {
  auto orb = CORBA::ORB_init(argc, argv);
  valuetest::register_factories(orb);
  auto factory = IDL::traits<DynAnyFactory>::narrow(orb->resolve_initial_references("DynAnyFactory"));
  int failed = 0;

  run("factory", [&]() {
    CHECK(factory);
    auto names = orb->list_initial_services();
    CHECK(std::find(names.begin(), names.end(), "DynAnyFactory") != names.end());
    CHECK_THROWS(CORBA::ORB::InvalidName, orb->register_initial_reference("DynAnyFactory", factory));
  }, failed);

  run("classes", [&]() {
    auto is = [&](const ref<CORBA::TypeCode>& tc, auto* tag) {
      using T = std::remove_pointer_t<decltype(tag)>;
      auto d = factory->create_dyn_any_from_type_code(tc);
      CHECK(narrow<T>(d));
      CHECK(d->type()->equal(tc));
      d->destroy();
    };
    is(A::_tc_Point, static_cast<DynStruct*>(nullptr));
    is(A::_tc_Oops, static_cast<DynStruct*>(nullptr));
    is(A::_tc_Choice, static_cast<DynUnion*>(nullptr));
    is(A::_tc_Shade, static_cast<DynEnum*>(nullptr));
    is(A::_tc_LongSeq, static_cast<DynSequence*>(nullptr));
    is(A::_tc_ShortArray, static_cast<DynArray*>(nullptr));
    is(A::_tc_Money, static_cast<DynFixed*>(nullptr));
    is(V::_tc_Point, static_cast<DynValue*>(nullptr));
    is(V::_tc_LongBox, static_cast<DynValueBox*>(nullptr));
    auto count = factory->create_dyn_any_from_type_code(A::_tc_Count);
    CHECK(!narrow<DynStruct>(count) && !narrow<DynEnum>(count));
    CHECK(count->_is_a("IDL:omg.org/DynamicAny/DynAny:1.0"));
    CHECK_THROWS(DynAnyFactory::InconsistentTypeCode,
                 factory->create_dyn_any_from_type_code(
                     rustorb::detail::tc_simple(CORBA::TCKind::tk_Principal)));
  }, failed);

  run("round_trip", [&]() {
    A::Node node("root", {A::Node("a", {}), A::Node("b", {A::Node("c", {})})});
    A::Choice choice;
    choice.s("three", 3);
    std::vector<CORBA::Any> values = {any_of(node), any_of(choice), any_of(A::Shade::DIM),
                                      any_of(any_of(A::Point(1, 2.5))),
                                      any_of(A::Oops("bad", 3))};
    CORBA::Any octets;
    octets <<= std::vector<uint8_t>{0, 0xff};
    octets.type(A::_tc_Octets);
    values.push_back(octets);
    for (const auto& a : values) {
      CORBA::Any got = factory->create_dyn_any(a)->to_any();
      CHECK(got == a);
    }
  }, failed);

  run("struct", [&]() {
    auto d = narrow<DynStruct>(factory->create_dyn_any_from_type_code(A::_tc_Point));
    d->insert_long(4);
    d->next();
    d->insert_double(0.5);
    CHECK(d->current_member_name() == "y");
    CHECK(d->current_member_kind() == CORBA::TCKind::tk_double);
    A::Point p;
    CHECK(d->to_any() >>= p);
    CHECK(p.x() == 4 && p.y() == 0.5);
    CHECK_THROWS(DynAny::TypeMismatch, d->insert_long(1));
    auto members = d->get_members();
    CHECK(members.size() == 2 && members[0].id() == "x" && members[1].id() == "y");
    members[0].value(any_of(int32_t{9}));
    d->set_members(members);
    CHECK((d->to_any() >>= p) && p.x() == 9);
    auto pairs = d->get_members_as_dyn_any();
    pairs[1].value()->insert_double(7.0);
    CHECK((d->to_any() >>= p) && p.y() == 7.0);
    members[1].id("z");
    CHECK_THROWS(DynAny::TypeMismatch, d->set_members(members));
  }, failed);

  run("union_and_enum", [&]() {
    auto d = narrow<DynUnion>(factory->create_dyn_any_from_type_code(A::_tc_Choice));
    auto disc = factory->create_dyn_any_from_type_code(CORBA::_tc_long);
    disc->insert_long(3);
    d->set_discriminator(disc);
    d->member()->insert_string("three");
    CHECK(d->discriminator_kind() == CORBA::TCKind::tk_long);
    CHECK(d->member_name() == "s");
    A::Choice c;
    CHECK(d->to_any() >>= c);
    CHECK(c._d() == 3 && c.s() == "three");
    auto e = narrow<DynEnum>(factory->create_dyn_any_from_type_code(A::_tc_Shade));
    e->set_as_string("DIM");
    A::Shade s = A::Shade::LIGHT;
    CHECK((e->to_any() >>= s) && s == A::Shade::DIM);
    CHECK(e->get_as_ulong() == 2);
    CHECK_THROWS(DynAny::InvalidValue, e->set_as_string("PINK"));
  }, failed);

  run("sequences", [&]() {
    auto d = narrow<DynSequence>(factory->create_dyn_any_from_type_code(A::_tc_LongSeq));
    d->insert_long_seq({1, 2, 3});
    CHECK(d->get_long_seq() == CORBA::LongSeq({1, 2, 3}));
    d->set_length(4);
    A::LongSeq v;
    CHECK((d->to_any() >>= v) && v == A::LongSeq({1, 2, 3, 0}));
    d->set_elements({any_of(int32_t{5})});
    auto elements = d->get_elements();
    int32_t x = 0;
    CHECK(elements.size() == 1 && (elements[0] >>= x) && x == 5);
    CHECK_THROWS(DynAny::TypeMismatch, d->set_elements({any_of(int16_t{5})}));
    auto o = factory->create_dyn_any_from_type_code(A::_tc_Octets);
    o->insert_octet_seq({'a', 'b'});
    CHECK(o->get_octet_seq() == CORBA::OctetSeq({'a', 'b'}));
    auto arr = narrow<DynArray>(factory->create_dyn_any_from_type_code(A::_tc_ShortArray));
    arr->insert_short_seq({1, 2, 3});
    CHECK(arr->get_elements_as_dyn_any()[2]->get_short() == 3);
    CHECK_THROWS(DynAny::InvalidValue, arr->insert_short_seq({1}));
  }, failed);

  run("any_and_typecode", [&]() {
    auto d = factory->create_dyn_any_from_type_code(CORBA::_tc_any);
    auto inner = factory->create_dyn_any_from_type_code(A::_tc_Point);
    inner->insert_long(2);
    d->insert_dyn_any(inner);
    CHECK(d->get_dyn_any()->equal(inner));
    A::Point p;
    CHECK((d->get_any() >>= p) && p.x() == 2);
    auto t = factory->create_dyn_any_from_type_code(CORBA::_tc_TypeCode);
    t->insert_typecode(A::_tc_Node);
    CHECK(t->get_typecode()->equal(A::_tc_Node));
    auto w = factory->create_dyn_any_from_type_code(CORBA::_tc_wstring);
    w->insert_wstring(L"wide");
    CHECK(w->get_wstring() == L"wide");
    CHECK_THROWS(CORBA::NO_IMPLEMENT, w->insert_abstract(nullptr));
  }, failed);

  run("valuetypes", [&]() {
    auto n = valuetest::node(1, nullptr);
    n->next(n);
    auto d = narrow<DynValue>(factory->create_dyn_any(any_of(n)));
    CHECK(!d->is_null());
    d->seek(1);
    CHECK(d->current_component()->equal(d));
    d->rewind();
    d->insert_long(5);
    ref<V::Node> got;
    CHECK(d->to_any() >>= got);
    CHECK(got->id() == 5 && got->next() == got);
    d->destroy();
    CHECK_THROWS(CORBA::OBJECT_NOT_EXIST, d->component_count());

    auto box = narrow<DynValueBox>(factory->create_dyn_any_from_type_code(V::_tc_LongBox));
    CHECK(box->is_null());
    box->set_boxed_value(any_of(int32_t{4}));
    int32_t x = 0;
    CHECK((box->get_boxed_value() >>= x) && x == 4);

    auto holder = factory->create_dyn_any_from_type_code(V::_tc_Pair);
    auto p = valuetest::point(1, 2);
    holder->insert_val(p);
    holder->next();
    holder->insert_val(p);
    V::Pair pair;
    CHECK(holder->to_any() >>= pair);
    CHECK(pair.first()->x() == 1 && pair.first()->y() == 2 && pair.second()->x() == 1);
    holder->rewind();
    auto first = ref<V::Point>(IDL::traits<V::Point>::narrow(holder->get_val()));
    CHECK(first && first->x() == 1);
  }, failed);

  run("truncation", [&]() {
    CORBA::Any a = any_of(valuetest::point3());
    a.type(V::_tc_Point);
    auto d = factory->create_dyn_any(a);
    CHECK(d->component_count() == 2);
    ref<V::Point> p;
    CHECK((d->to_any() >>= p) && p && !dynamic_cast<valuetest::Point3Impl*>(&*p));
    CHECK_THROWS(MustTruncate, factory->create_dyn_any_without_truncation(a));
    CHECK_THROWS(MustTruncate, factory->create_multiple_dyn_anys({a}, false));
    CHECK(factory->create_multiple_dyn_anys({a}, true).size() == 1);
    CHECK(factory->create_multiple_anys({d}).size() == 1);
  }, failed);

  orb->destroy();
  std::cout << (failed ? "FAILED" : "all passed") << std::endl;
  return failed ? 1 : 0;
}
